 "content": "from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for a, b in ((x-1,y), (x+1,y), (x,y-1), (x,y+1)):
                    if 0 <= a < h and 0 <= b < w and grid[a][b] == 0 and (a,b) not in seen:
                        seen.add((a,b))
                        q.append((a,b))
            components.append(cells)
    if components:
        largest = max(components, key=len)
        smallest = min(components, key=len)
        for r, c in largest:
            out[r][c] = 8
        for r, c in smallest:
            out[r][c] = 7
    return out

if __name__ == '__main__':
